# Step1: Extract all players who have won singles titles
singles_players = set()
for col in ['men \'s singles', 'women \'s singles']:
    for name in df[col]:
        singles_players.add(name)

# Step2: Extract all players who have won doubles titles
doubles_players = set()
for col in ['men \'s doubles', 'women \'s doubles']:
    for name in df[col].str.split().str.join(' ').str.split(' '):
        for name_part in name:
            if name_part.isalpha():
                doubles_players.add(name_part)

# Step3: Count the number of players who have won singles titles
total_singles_players = len(singles_players)

# Step4: Count the number of players who have won both singles and doubles titles
players_with_both = singles_players.intersection(doubles_players)
total_players_with_both = len(players_with_both)

# Step5: Calculate the probability of a singles title winner also winning a doubles title
if total_singles_players > 0:
    prob_singles_to_doubles = total_players_with_both / total_singles_players
else:
    prob_singles_to_doubles = 0

# Step6: Calculate the overall probability of a player winning a doubles title
all_players = set()
for col in df.columns[1:]:
    for name in df[col].str.split().str.join(' ').str.split(' '):
        for name_part in name:
            if name_part.isalpha():
                all_players.add(name_part)

total_all_players = len(all_players)
prob_doubles = len(doubles_players) / total_all_players

# Step7: Compare the two probabilities
final_answer_value = 'Yes' if prob_singles_to_doubles > prob_doubles else 'No'

